    def flight_information_encode(self, time_boot_ms: int, arming_time_utc: int, takeoff_time_utc: int, flight_uuid: int, landing_time: int = 0) -> MAVLink_flight_information_message:
        """
        Flight information.         This includes time since boot for arm,
        takeoff, and land, and a flight number.         Takeoff and
        landing values reset to zero on arm.         This can be
        requested using MAV_CMD_REQUEST_MESSAGE.         Note, some
        fields are misnamed - timestamps are from boot (not UTC) and
        the flight_uuid is a sequence number.

        time_boot_ms              : Timestamp (time since system boot). [ms] (type:uint32_t)
        arming_time_utc           : Timestamp at arming (since system boot). Set to 0 on boot. Set value on arming. Note, field is misnamed UTC. [us] (type:uint64_t)
        takeoff_time_utc          : Timestamp at takeoff (since system boot). Set to 0 at boot and on arming. Note, field is misnamed UTC. [us] (type:uint64_t)
        flight_uuid               : Flight number. Note, field is misnamed UUID. (type:uint64_t)
        landing_time              : Timestamp at landing (in ms since system boot). Set to 0 at boot and on arming. [ms] (type:uint32_t)

        """
        return MAVLink_flight_information_message(time_boot_ms, arming_time_utc, takeoff_time_utc, flight_uuid, landing_time)

    def flight_information_send(self, time_boot_ms: int, arming_time_utc: int, takeoff_time_utc: int, flight_uuid: int, landing_time: int = 0, force_mavlink1: bool = False) -> None:
        """
        Flight information.         This includes time since boot for arm,
        takeoff, and land, and a flight number.         Takeoff and
        landing values reset to zero on arm.         This can be
        requested using MAV_CMD_REQUEST_MESSAGE.         Note, some
        fields are misnamed - timestamps are from boot (not UTC) and
        the flight_uuid is a sequence number.

        time_boot_ms              : Timestamp (time since system boot). [ms] (type:uint32_t)
        arming_time_utc           : Timestamp at arming (since system boot). Set to 0 on boot. Set value on arming. Note, field is misnamed UTC. [us] (type:uint64_t)
        takeoff_time_utc          : Timestamp at takeoff (since system boot). Set to 0 at boot and on arming. Note, field is misnamed UTC. [us] (type:uint64_t)
        flight_uuid               : Flight number. Note, field is misnamed UUID. (type:uint64_t)
        landing_time              : Timestamp at landing (in ms since system boot). Set to 0 at boot and on arming. [ms] (type:uint32_t)

        """
        self.send(self.flight_information_encode(time_boot_ms, arming_time_utc, takeoff_time_utc, flight_uuid, landing_time), force_mavlink1=force_mavlink1)

